<script setup>
import { ref } from 'vue'; import { Head,Link,router } from '@inertiajs/vue3'; import AppLayout from '@/Layouts/AppLayout.vue'; import Button from '@/Components/UI/Button.vue'; import Icon from '@/Components/UI/Icon.vue'; import HrNav from '../Partials/HrNav.vue'; import {usePermissions} from '@/composables/usePermissions';
defineOptions({layout:AppLayout}); const props=defineProps({records:Object,employees:[Array,Object],filters:Object,summary:Object}); const {can}=usePermissions(); const from=ref(props.filters.from),to=ref(props.filters.to),employee=ref(props.filters.employee??''); const filter=()=>router.get('/administration/attendance',{from:from.value,to:to.value,employee:employee.value||undefined},{preserveState:true,replace:true}); const dateTime=(v)=>v?new Intl.DateTimeFormat('fr-FR',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'—';
</script>
<template><Head title="Présences"/><div class="space-y-5"><HrNav/><header class="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between"><div><p class="text-xs font-bold uppercase tracking-[.15em] text-violet-600">Temps constaté</p><h1 class="mt-1 font-heading text-3xl font-bold text-slate-800 dark:text-white">Présences</h1><p class="mt-2 text-sm text-slate-500">Journal des entrées et sorties du personnel.</p></div><div class="flex flex-wrap gap-2"><Button v-if="can('attendance.print')" :as="Link" :href="`/administration/attendance/print?from=${from}&to=${to}`" size="rg" variant="white-outline"><Icon name="printer"/><span class="ms-2">Imprimer</span></Button><Button v-if="can('attendance.export')" as="a" :href="`/administration/attendance/export?from=${from}&to=${to}`" size="rg" variant="white-outline"><Icon name="download"/><span class="ms-2">Exporter</span></Button><Button v-if="can('attendance.create')" :as="Link" href="/administration/attendance/create" size="rg"><Icon name="plus"/><span class="ms-2">Nouvelle présence</span></Button></div></header><section class="grid gap-3 sm:grid-cols-3"><div v-for="item in [{label:'Sessions',value:summary.sessions},{label:'Employés concernés',value:summary.employees},{label:'Sessions ouvertes',value:summary.open}]" :key="item.label" class="rounded-xl border border-gray-200 bg-white p-4 shadow-sm dark:border-gray-900 dark:bg-gray-950"><p class="text-xs font-bold uppercase tracking-wide text-slate-400">{{item.label}}</p><p class="mt-2 text-2xl font-black text-slate-800 dark:text-white">{{item.value}}</p></div></section><section class="overflow-hidden rounded-xl border border-gray-200 bg-white shadow-sm dark:border-gray-900 dark:bg-gray-950"><form class="grid gap-3 border-b border-gray-200 p-4 sm:grid-cols-2 lg:grid-cols-[1fr_1fr_2fr_auto] dark:border-gray-900" @submit.prevent="filter"><input v-model="from" type="date" class="h-10 rounded-lg border border-gray-200 px-3 text-sm dark:border-gray-800 dark:bg-gray-950"><input v-model="to" type="date" class="h-10 rounded-lg border border-gray-200 px-3 text-sm dark:border-gray-800 dark:bg-gray-950"><select v-model="employee" class="h-10 rounded-lg border border-gray-200 px-3 text-sm dark:border-gray-800 dark:bg-gray-950 dark:text-white"><option value="">Tous les employés</option><option v-for="item in employees" :key="item.uuid" :value="item.uuid">{{item.employee_number}} · {{item.name}}</option></select><Button size="rg">Appliquer</Button></form><div class="overflow-x-auto"><table class="w-full min-w-[850px]"><thead><tr class="bg-gray-50/70 text-xs font-bold uppercase tracking-wide text-slate-400 dark:bg-gray-1000/40"><th class="px-5 py-3 text-start">Employé</th><th class="px-5 py-3 text-start">Entrée</th><th class="px-5 py-3 text-start">Sortie</th><th class="px-5 py-3 text-start">Durée</th><th class="px-5 py-3 text-start">Observation</th><th class="px-5 py-3 text-end">Action</th></tr></thead><tbody><tr v-for="record in records.data" :key="record.uuid" class="border-t border-gray-100 dark:border-gray-900"><td class="px-5 py-4"><strong class="text-sm text-slate-800 dark:text-white">{{record.employee.name}}</strong><p class="font-mono text-xs text-slate-400">{{record.employee.employee_number}}</p></td><td class="px-5 py-4 text-sm">{{dateTime(record.started_at)}}</td><td class="px-5 py-4 text-sm">{{dateTime(record.ended_at)}}</td><td class="px-5 py-4"><span :class="['rounded-full px-2.5 py-1 text-xs font-bold',record.minutes===null?'bg-amber-50 text-amber-700':'bg-violet-50 text-violet-700']">{{record.minutes===null?'Ouverte':`${Math.floor(record.minutes/60)} h ${record.minutes%60} min`}}</span></td><td class="max-w-xs px-5 py-4 text-sm text-slate-500">{{record.observation||'—'}}</td><td class="px-5 py-4 text-end"><Button v-if="can('attendance.update')" :as="Link" :href="`/administration/attendance/${record.uuid}/edit`" icon size="rg" variant="white-outline"><Icon name="edit"/></Button></td></tr><tr v-if="!records.data.length"><td colspan="6" class="py-14 text-center text-sm text-slate-400">Aucune présence sur cette période.</td></tr></tbody></table></div></section></div></template>
